use Filament\SpatieLaravelTranslatablePlugin;
use Illuminate\Session\Middleware\StartSession;
use Illuminate\Cookie\Middleware\EncryptCookies;
use Filament\Http\Middleware\AuthenticateSession;
use FilamentThemes\Minimal\Theme as MinimalTheme;
use BezhanSalleh\FilamentShield\FilamentShieldPlugin;
use Illuminate\Routing\Middleware\SubstituteBindings;
use Illuminate\View\Middleware\ShareErrorsFromSession;
use AtrioTeam\FilamentHelper\Filament\Pages\Auth\Login;
use Filament\Http\Middleware\DisableBladeIconComponents;
use Filament\Http\Middleware\DispatchServingFilamentEvent;
use Illuminate\Foundation\Http\Middleware\VerifyCsrfToken;
use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;

/**
 * Default configurator for the panel,
 * called by the AdminPanelProvider stub.
 */
class PanelDefaults
{
    public static function make(Panel $panel): void
    {
        /**
         * Sticky form actions, aligned to the right
         */
        \Filament\Pages\Page::stickyFormActions(true);
        Page::formActionsAlignment(Alignment::Right);

        /**
         * Custom css for the project.
         * This has been commented out, it should be applied in a service provider
         * of the main application.
         */
        if (app()->runningInConsole() === false) {
            FilamentAsset::register([
                // Css::make('filament-custom', Vite::asset('resources/sass/filament-custom.scss'))
            ]);
        }


        $panel->login(Login::class)
        ->id('admin')
        ->default()
        ->path('admin')
        ->viteTheme('vendor/atrioteam/filament-helper/resources/theme/theme.css')
        ->brandName(config('app.name'))
        ->brandLogo(fn () => view('filament-helper::logo.admin-logo', [
            'logo' => asset('img/logo.svg'),
        ]))
        ->maxContentWidth(Width::Full)
        ->discoverResources(in: app_path('Filament/Resources'), for: 'App\\Filament\\Resources')
        ->discoverPages(in: app_path('Filament/Pages'), for: 'App\\Filament\\Pages')
        ->pages([
            \App\Filament\Pages\Dashboard::class,
        ])
        ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\\Filament\\Widgets')
        ->widgets([
            AccountWidget::class,
            FilamentInfoWidget::class,
        ])
        ->middleware([
            EncryptCookies::class,
            AddQueuedCookiesToResponse::class,
            StartSession::class,
            AuthenticateSession::class,
            ShareErrorsFromSession::class,
            VerifyCsrfToken::class,
            SubstituteBindings::class,
            DisableBladeIconComponents::class,
            DispatchServingFilamentEvent::class,
        ])
        ->plugins([
            FilamentShieldPlugin::make(),
            MinimalTheme::make(),
        ])
        ->authMiddleware([
            Authenticate::class,
        ])
        // to be called after plugin registration, to overwrite colors set by MinimalTheme
        ->colors([
            'primary' => Color::hex('#04A9F5'),
        ])
        // custom avatar provider
        ->defaultAvatarProvider(AvatarsProvider::class)
        // load fonts from local filesystem
        ->font(
            'Inter',
            url: asset('fonts/filament-helper/fonts.css'),
            provider: LocalFontProvider::class,
        )
        ->globalSearch(false)
        ->unsavedChangesAlerts(app()->environment('production'));
    }
}

