5	namespace App\Sync;
6	
7	use Generator;
8	use Illuminate\Support\Carbon;
9	use Illuminate\Support\Facades\Http;
10	
11	/**
12	 * Client verso l'API esterna dell'hub (design doc Parte 1, roadmap hub #24).
13	 * Stateless, un solo token di servizio, paginazione page/per_page.
14	 */
15	class HubClient
16	{
17	    /**
18	     * Itera le pagine di una risorsa, yieldando l'array `data` di ciascuna.
19	     *
20	     * @return Generator<int, array<int, array<string, mixed>>>
21	     */
22	    public function paginate(string $resource, ?Carbon $updatedSince = null): Generator
23	    {
24	        $page = 1;
25	        $lastPage = 1;
26	
27	        do {
28	            $response = $this->request()->get($resource, array_filter([
29	                'page' => $page,
30	                'per_page' => config('digital-hub.per_page'),
31	                'updated_since' => $updatedSince?->toIso8601String(),
32	            ]));
33	
34	            if ($response->failed()) {
35	                throw new HubApiException(
36	                    "Chiamata a [{$resource}] pagina {$page} fallita con status {$response->status()}: {$response->body()}",
37	                );
38	            }
39	
40	            /** @var array{data?: array<int, array<string, mixed>>, meta?: array{last_page?: int}} $body */
41	            $body = $response->json();
42	
43	            yield $body['data'] ?? [];
44	
45	            $lastPage = (int) ($body['meta']['last_page'] ?? 1);
46	            $page++;
47	        } while ($page <= $lastPage);
48	    }
49	
50	    private function request(): \Illuminate\Http\Client\PendingRequest
51	    {
52	        /** @var string $configuredBaseUrl */
53	        $configuredBaseUrl = config('digital-hub.base_url');
54	        /** @var string $token */
55	        $token = config('digital-hub.token');
56	
57	        return Http::baseUrl(rtrim($configuredBaseUrl, '/') . '/api/v1')->withToken($token);
58	    }
59	}
