11	 * Aggiungere una nuova entità è dichiarativo: non serve toccare motore o UI.
12	 */
13	class SyncRegistry
14	{
15	    public static function has(string $slug): bool
16	    {
17	        return array_key_exists($slug, self::allResources());
18	    }
19	
20	    public static function label(string $slug): string
21	    {
22	        return self::definition($slug)['label'];
23	    }
24	
25	    public static function syncerFor(string $slug): Syncer
26	    {
27	        $class = self::definition($slug)['syncer'];
28	
29	        /** @var Syncer $syncer */
30	        $syncer = app($class);
31	
32	        return $syncer;
33	    }
34	
35	    /**
36	     * @return array<string, array{label: string, syncer: class-string<Syncer>}>
37	     */
38	    public static function all(): array
39	    {
40	        return self::allResources();
41	    }
42	
43	    /**
44	     * @return array{label: string, syncer: class-string<Syncer>}
45	     */
46	    private static function definition(string $slug): array
47	    {
48	        $definition = self::allResources()[$slug] ?? null;
49	
50	        if ($definition === null) {
51	            throw new InvalidArgumentException("Risorsa di sync [{$slug}] non registrata.");
52	        }
53	
54	        return $definition;
55	    }
56	
57	    /**
58	     * @return array<string, array{label: string, syncer: class-string<Syncer>}>
59	     */
60	    private static function allResources(): array
61	    {
62	        /** @var array<string, array{label: string, syncer: class-string<Syncer>}> $resources */
63	        $resources = config('sync.resources', []);
64	
65	        return $resources;
66	    }
