5	namespace App\Sync;
6	
7	use App\Enums\SyncStatus;
8	use App\Models\Product;
9	use App\Models\SyncRun;
10	use Throwable;
11	
12	/**
13	 * Pull incrementale dei `Product` dall'hub (roadmap hub #24). Il payload
14	 * arriva già risolto (attributi PIM tradotti): questo syncer non conosce lo
15	 * schema PIM, si limita a fare mirror del payload.
16	 */
17	class ProductSyncer implements Syncer
18	{
19	    public function __construct(private readonly HubClient $client = new HubClient())
20	    {
21	    }
22	
23	    public function sync(SyncRun $run): void
24	    {
25	        $watermark = $this->watermark();
26	        $itemErrors = [];
27	
28	        foreach ($this->client->paginate('products', $watermark) as $page) {
29	            foreach ($page as $item) {
30	                try {
31	                    $created = $this->upsert($item);
32	
33	                    $run->increment($created ? 'created_count' : 'updated_count');
34	                } catch (Throwable $e) {
35	                    $run->increment('failed_count');
36	                    $itemErrors[] = [
37	                        'global_id' => $item['global_id'] ?? null,
38	                        'message' => $e->getMessage(),
39	                    ];
40	                }
41	            }
42	        }
43	
44	        if ($itemErrors !== []) {
45	            $run->update(['item_errors' => $itemErrors]);
46	        }
47	    }
48	
49	    /**
50	     * @param array<string, mixed> $item
51	     * @return bool true se il record locale non esisteva ancora (creato)
52	     */
53	    private function upsert(array $item): bool
54	    {
55	        $exists = Product::where('global_id', $item['global_id'])->exists();
56	
57	        Product::updateOrCreate(
58	            ['global_id' => $item['global_id']],
59	            [
60	                'name' => $item['name'],
61	                'slug' => $item['slug'],
62	                'category_global_id' => $item['category_global_id'] ?? null,
63	                'product_type_global_id' => $item['product_type_global_id'] ?? null,
64	                'attributes' => $item['attributes'] ?? [],
65	                'hub_updated_at' => $item['updated_at'] ?? null,
66	            ],
67	        );
68	
69	        return ! $exists;
70	    }
71	
72	    private function watermark(): ?\Illuminate\Support\Carbon
73	    {
74	        $lastSuccess = SyncRun::query()
75	            ->where('resource', 'products')
76	            ->where('status', SyncStatus::Success)
77	            ->latest('started_at')
78	            ->first();
79	
80	        if ($lastSuccess === null) {
81	            return null;
82	        }
83	
84	        /** @var \Illuminate\Support\Carbon|null $startedAt */
85	        $startedAt = $lastSuccess->started_at;
86	
87	        return $startedAt;
88	    }
89	}
