private function errorsModalContent(SyncRun $record): Htmlable
{
    $lines = [];

    if (filled($record->error)) {
        $lines[] = e($record->error);
    }

    /** @var array<int, array{global_id?: string, message?: string}> $itemErrors */
    $itemErrors = $record->item_errors ?? [];

    foreach ($itemErrors as $itemError) {
        $lines[] = e(($itemError['global_id'] ?? '?') . ': ' . ($itemError['message'] ?? ''));
    }

    return new HtmlString('<pre class="whitespace-pre-wrap text-sm">' . implode("\n", $lines) . '</pre>');
}

