20	use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
21	
22	/**
23	 * Storico sync per una singola risorsa registrata in SyncRegistry, con action
24	 * di trigger manuale (design doc Parte 2: "Import dati" è UI di dominio, non
25	 * log tecnico).
26	 */
27	class SyncResourceDetail extends Page implements Tables\Contracts\HasTable
28	{
29	    use Tables\Concerns\InteractsWithTable;
30	
31	    protected static ?string $slug = 'sync/{resource}';
32	
33	    protected static bool $shouldRegisterNavigation = false;
34	
35	    public string $resource;
36	
37	    public function mount(string $resource): void
38	    {
39	        if (! SyncRegistry::has($resource)) {
40	            throw new NotFoundHttpException("Risorsa di sync [{$resource}] non registrata.");
41	        }
42	
43	        $this->resource = $resource;
44	    }
45	
46	    public function getTitle(): string | Htmlable
47	    {
48	        return 'Sincronizzazione — ' . SyncRegistry::label($this->resource);
49	    }
50	
51	    public function content(Schema $schema): Schema
52	    {
53	        return $schema->components([
54	            EmbeddedTable::make(),
55	        ]);
56	    }
57	
58	    public function table(Table $table): Table
59	    {
60	        return $table
61	            ->query(fn () => SyncRun::query()->where('resource', $this->resource))
62	            ->defaultSort('started_at', 'desc')
63	            ->poll('5s')
64	            ->columns([
65	                Tables\Columns\TextColumn::make('started_at')
66	                    ->label('Avviato')
67	                    ->dateTime()
68	                    ->placeholder('—')
69	                    ->sortable(),
70	                Tables\Columns\TextColumn::make('finished_at')
71	                    ->label('Terminato')
72	                    ->dateTime()
73	                    ->placeholder('—'),
74	                Tables\Columns\TextColumn::make('status')
75	                    ->label('Esito')
76	                    ->badge()
77	                    ->formatStateUsing(fn (SyncStatus $state): string => $state->label())
78	                    ->color(fn (SyncStatus $state): string => $state->color()),
79	                Tables\Columns\TextColumn::make('created_count')->label('Creati'),
80	                Tables\Columns\TextColumn::make('updated_count')->label('Aggiornati'),
81	                Tables\Columns\TextColumn::make('failed_count')
82	                    ->label('Falliti')
83	                    ->color(fn (int $state): ?string => $state > 0 ? 'danger' : null),
84	            ])
85	            ->recordActions([
86	                Action::make('errors')
87	                    ->label('Errori')
88	                    ->icon('heroicon-o-exclamation-triangle')
89	                    ->color('danger')
90	                    ->visible(fn (SyncRun $record): bool => filled($record->error) || filled($record->item_errors))
91	                    ->modalHeading('Errori del sync')
92	                    ->modalContent(fn (SyncRun $record) => $this->errorsModalContent($record))
93	                    ->modalSubmitAction(false)
94	                    ->modalCancelActionLabel('Chiudi'),
95	            ])
96	            ->emptyStateHeading('Nessun sync eseguito finora');
97	    }
98	
99	    protected function getHeaderActions(): array
100	    {
101	        return [
102	            Action::make('import')
103	                ->label('Importa dati ora')
104	                ->icon('heroicon-o-arrow-path')
105	                ->disabled(fn (): bool => SyncRun::query()
106	                    ->where('resource', $this->resource)
107	                    ->whereIn('status', [SyncStatus::Pending, SyncStatus::Running])
108	                    ->exists())
109	                ->action(function (): void {
110	                    $run = SyncRun::create([
111	                        'resource' => $this->resource,
112	                        'status' => SyncStatus::Pending,
113	                    ]);
114	
115	                    RunSyncJob::dispatch($run->id);
116	
117	                    Notification::make()
118	                        ->title('Sync avviato')
119	                        ->success()
120	                        ->send();
121	                }),
122	        ];
123	    }
124	
