126	    {
127	        $lines = [];
128	
129	        if (filled($record->error)) {
130	            $lines[] = e($record->error);
131	        }
132	
133	        /** @var array<int, array{global_id?: string, message?: string}> $itemErrors */
134	        $itemErrors = $record->item_errors ?? [];
135	
136	        foreach ($itemErrors as $itemError) {
137	            $lines[] = e(($itemError['global_id'] ?? '?') . ': ' . ($itemError['message'] ?? ''));
138	        }
139	
140	        return new HtmlString('<span class="text-sm">' . implode("\n", $lines) . '</span>');
141	    }
