1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Sync;
6	
7	use App\Models\Product;
8	use AtrioTeam\HubSync\HubClient;
9	use AtrioTeam\HubSync\Models\SyncRun;
10	use AtrioTeam\HubSync\Syncer;
11	use AtrioTeam\HubSync\SyncStatus;
12	use Throwable;
13	
14	/**
15	 * Pull incrementale dei `Product` dall'hub (roadmap hub #24). Il payload
16	 * arriva già risolto (attributi PIM tradotti): questo syncer non conosce lo
17	 * schema PIM, si limita a fare mirror del payload.
18	 */
19	class ProductSyncer implements Syncer
20	{
21	    public function __construct(private readonly HubClient $client = new HubClient())
22	    {
23	    }
24	
25	    public function sync(SyncRun $run): void
26	    {
27	        $watermark = $this->watermark();
28	        $itemErrors = [];
29	
30	        foreach ($this->client->paginate('products', $watermark) as $page) {
31	            foreach ($page as $item) {
32	                try {
33	                    $created = $this->upsert($item);
34	
35	                    $run->increment($created ? 'created_count' : 'updated_count');
36	                } catch (Throwable $e) {
37	                    $run->increment('failed_count');
38	                    $itemErrors[] = [
39	                        'global_id' => $item['global_id'] ?? null,
40	                        'message' => $e->getMessage(),
41	                    ];
42	                }
43	            }
44	        }
45	
46	        if ($itemErrors !== []) {
47	            $run->update(['item_errors' => $itemErrors]);
48	        }
49	    }
50	
51	    /**
52	     * @param array<string, mixed> $item
53	     * @return bool true se il record locale non esisteva ancora (creato)
54	     */
55	    private function upsert(array $item): bool
56	    {
57	        $exists = Product::where('global_id', $item['global_id'])->exists();
58	
59	        Product::updateOrCreate(
60	            ['global_id' => $item['global_id']],
61	            [
62	                'name' => $item['name'],
63	                'slug' => $item['slug'],
64	                'category_global_id' => $item['category_global_id'] ?? null,
65	                'product_type_global_id' => $item['product_type_global_id'] ?? null,
66	                'attributes' => $item['attributes'] ?? [],
67	                'hub_updated_at' => $item['updated_at'] ?? null,
68	            ],
69	        );
70	
71	        return ! $exists;
72	    }
73	
74	    private function watermark(): ?\Illuminate\Support\Carbon
75	    {
76	        $lastSuccess = SyncRun::query()
77	            ->where('resource', 'products')
78	            ->where('status', SyncStatus::Success)
79	            ->latest('started_at')
80	            ->first();
81	
82	        if ($lastSuccess === null) {
83	            return null;
84	        }
85	
86	        /** @var \Illuminate\Support\Carbon|null $startedAt */
87	        $startedAt = $lastSuccess->started_at;
88	
89	        return $startedAt;
90	    }
91	}
